# مراجعة الشروح الشاملة، الدفعة 1 (طلب المستخدم 2026-11-25): python3 data/gharib/audit/batch1.py
import json
S={
'G03':('«تتفطّر قدماه»: تتشقّق. وفي رواية: «حتى تورّمت»، قال ابن حجر: «ولا اختلاف بين هذه الروايات، فإنه إذا حصل الانتفاخ أو الورم حصل الزلع والتشقّق».','فتح الباري لابن حجر 3/15'),
'KN12':('«على قراريط»: قال ابن حجر: قال سويد بن سعيد أحد رواته: «يعني كل شاة بقيراط، يعني القيراط الذي هو جزء من الدينار أو الدرهم»، وقال إبراهيم الحربي: «قراريط اسم موضع بمكة»، ورجّح ابن حجر الأول «لأن أهل مكة لا يعرفون بها مكانًا يقال له قراريط». فكان ﷺ يرعى الغنم بأجر يسير.','فتح الباري لابن حجر 4/441'),
'KN23':('«فغطّه»: قال ابن الأثير: «الغطّ: العصر الشديد والكبس»؛ أي ضمّه الملك إليه ضمًّا شديدًا. «قيل: إنما غطّه ليختبره هل يقول من تلقاء نفسه شيئًا».','النهاية في غريب الحديث لابن الأثير 3/373'),
'KN24':('«زمّلوني»: لفّوني بالثياب. قال ابن حجر: «والتزميل التلفيف، وقال ذلك لشدّة ما لحقه من هول الأمر، وجرت العادة بسكون الرِّعدة بالتلفيف».','فتح الباري لابن حجر 8/719'),
'KN49':('«سَحوليّة»: قال ابن حجر: «يُروى بضمّ أوّله، ويُروى بفتحه، نسبةً إلى سَحول قرية باليمن»، وفي رواية: «من كُرسف»، والكرسف: القطن. فهي أثواب بيض من قطن اليمن.','فتح الباري لابن حجر 3/140'),
'SH04':('«يسرد سردكم»: قال ابن الأثير: «أي يتابعه ويستعجل فيه». فكان ﷺ يتكلّم على مهل، ويفصل بين كلامه حتى يُحفظ.','النهاية في غريب الحديث لابن الأثير 2/358'),
'AD14':('«دع ما يريبك إلى ما لا يريبك»: قال ابن الأثير: «يُروى بفتح الياء وضمّها؛ أي: دع ما تشكّ فيه إلى ما لا تشكّ فيه».','النهاية في غريب الحديث لابن الأثير 2/286'),
'C32':('«يا ذا الأذنين»: قال ابن الأثير: «قيل معناه الحضّ على حسن الاستماع والوعي… وقيل إن هذا القول من جملة مزحه ﷺ ولطيف أخلاقه».','النهاية في غريب الحديث لابن الأثير 1/34'),
'KN02':('«الحاشر الذي يُحشر الناس على قدمي»: قال ابن الأثير: «أي على أثري»، و«العاقب»: «هو آخر الأنبياء».','النهاية في غريب الحديث لابن الأثير 4/25 و3/268'),
'SH05':('«الشَّفرة»: قال ابن الأثير: «السكين العريضة». فكان ﷺ يقطع اللحم لضيفه بيده.','النهاية في غريب الحديث لابن الأثير 2/484'),
'HB38':('«جَور»: ظلم. قال ابن الأثير: «الجور بمعنى الظلم». فتفضيل أحد الأولاد بالعطيّة دون إخوته ظلمٌ لهم.','النهاية في غريب الحديث لابن الأثير 1/313'),
}
d={c['id']:c for c in json.load(open('public/cards.json'))['cards']}
K=[]
for i,(t,s) in S.items():
    c=dict(d[i]); assert not c.get('sharh'); c['sharh']=dict(text=t,source=s); K.append(c)
json.dump({'cards':K,'quiz':[]},open('data/gharib/audit/batch1.json','w'),ensure_ascii=False,indent=1)
print(len(K))
